1	using chatai.Core.DTO;
2	using chatai.Core.Models.reponse.FileManager;
3	using chatai.Core.Models.request.FileManager;
4	using chatai_admin.Controllers.Base;
5	using Microsoft.AspNetCore.Mvc;
6	using ntu.Common.Utility.Exception;
7	using ntu.Common.Utility.Helper;
8	
9	namespace chatai_admin.Controllers
10	{
11	    [Route("api/[controller]/[action]")]
12	    public class FileManagerController : BaseApiController
13	    {
14	        private readonly string _baseFolder = Path.Combine(Directory.GetCurrentDirectory(), "App_Data", "doc");
15	
16	        [HttpPost]
17	        public IActionResult Tree([FromBody] ListRequest request)
18	        {
19	            var folder = string.IsNullOrEmpty(request.subfolder) ? _baseFolder : Path.Combine(_baseFolder, request.subfolder);
20	            if (!Directory.Exists(folder))
21	                throw new CustomException("資料夾不存在");
22	
23	            var tree = GetTree(folder);
24	            // 強制第一層名稱為 root
25	            tree.Name = "root";
26	
27	            var model = AutoMapperHelper.Map<FileNode, ListResponse>(tree);
28	
29	            return Ok(model);
30	        }
31	
32	        [HttpPost]
33	        public IActionResult CreateFolder([FromBody] CreateFolderRequest request)
34	        {
35	            if (string.IsNullOrWhiteSpace(request.FolderName))
36	                throw new CustomException("請輸入資料夾名稱");
37	
38	            // 檢查資料夾名稱是否包含不允許的字元
39	            char[] invalidChars = Path.GetInvalidFileNameChars();
40	            if (request.FolderName.IndexOfAny(invalidChars) >= 0)
41	                throw new CustomException("資料夾名稱包含不允許的字元");
42	
43	            // 計算父資料夾路徑
44	            var parentPath = string.IsNullOrEmpty(request.ParentFolder)
45	                ? _baseFolder
46	                : Path.Combine(_baseFolder, request.ParentFolder);
47	
48	            if (!Directory.Exists(parentPath))
49	                Directory.CreateDirectory(parentPath);
50	
51	            var newFolderPath = Path.Combine(parentPath, request.FolderName);
52	
53	            if (Directory.Exists(newFolderPath))
54	                throw new CustomException("資料夾已存在");
55	
56	            Directory.CreateDirectory(newFolderPath);
57	
58	            return Ok();
59	        }
60	
61	        [HttpPost]
62	        public async Task<IActionResult> Upload([FromForm] IFormFile file, [FromForm] string? subfolder = null)
63	        {
64	            if (file == null || file.Length == 0)
65	                throw new CustomException("未選擇檔案");
66	
67	            var allowedExtensions = new[] { ".md", ".pdf", ".xls", ".xlsx", ".csv", ".docx" };
68	            var ext = Path.GetExtension(file.FileName).ToLowerInvariant();
69	            if (!allowedExtensions.Contains(ext))
70	                throw new CustomException("只允許 md、pdf、excel、csv、docx 檔案");
71	
72	            var folder = string.IsNullOrEmpty(subfolder) ? _baseFolder : Path.Combine(_baseFolder, subfolder);
73	            if (!Directory.Exists(folder))
74	                Directory.CreateDirectory(folder);
75	
76	            var fileName = Path.GetFileNameWithoutExtension(file.FileName);
77	            var filePath = Path.Combine(folder, file.FileName);
78	            int count = 1;
79	            // 自動編號
80	            while (System.IO.File.Exists(filePath))
81	            {
82	                var newFileName = $"{fileName}({count}){ext}";
83	                filePath = Path.Combine(folder, newFileName);
84	                count++;
85	            }
86	
87	            using (var stream = new FileStream(filePath, FileMode.Create))
88	            {
89	                await file.CopyToAsync(stream);
90	            }
91	            return Ok();
92	        }
93	
94	        [HttpPost]
95	        public IActionResult DeleteFolder([FromBody] DeleteFolderRequest request)
96	        {
97	            if (string.IsNullOrWhiteSpace(request.FolderPath))
98	                throw new CustomException("未指定資料夾路徑");
99	
100	            var folder = Path.Combine(_baseFolder, request.FolderPath);
101	            if (!Directory.Exists(folder))
102	                throw new CustomException("資料夾不存在");
103	
104	            // 遞迴刪除資料夾及內容
105	            Directory.Delete(folder, true);
106	
107	            return Ok();
108	        }
109	
110	        [HttpPost]
111	        public IActionResult Delete([FromBody] DeleteRequest request)
112	        {
113	            if (string.IsNullOrEmpty(request.FileName))
114	                throw new CustomException("未指定檔案名稱");
115	
116	            var folder = string.IsNullOrEmpty(request.Subfolder) ? _baseFolder : Path.Combine(_baseFolder, request.Subfolder);
117	            var filePath = Path.Combine(folder, request.FileName);
118	            if (!System.IO.File.Exists(filePath))
119	                throw new CustomException("檔案不存在");
120	
121	            System.IO.File.Delete(filePath);
122	
123	            return Ok();
124	        }
125	
126	        private FileNode GetTree(string path)
127	        {
128	            var node = new FileNode
129	            {
130	                Name = Path.GetFileName(path),
131	                IsFolder = true,
132	                Children = new List<FileNode>()
133	            };
134	
135	            // 資料夾
136	            foreach (var dir in Directory.GetDirectories(path))
137	            {
138	                node.Children.Add(GetTree(dir));
139	            }
140	            // 檔案
